template:
% 参数由系统自动注入；梯形：上下底水平平行
% 视觉归一化：把最长边（含两腰）缩放到 6 个坐标单位，线宽字体不缩放；装饰尺寸已做 figscale 补偿
\pgfmathsetmacro{\legad}{sqrt(\dx*\dx + \h*\h)}
\pgfmathsetmacro{\legbc}{sqrt((\ab-\dx-\topbase)^2 + \h*\h)}
\pgfmathsetmacro{\figscale}{6 / max(\ab, \topbase, \legad, \legbc)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \coordinate (D) at (\dx,\h);
  \coordinate (C) at (\dx+\topbase,\h);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % ∠A 直角记号（沿 AB 与 AD 方向）
  \ifnum\rightmarka>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \ab*0.2, \legad*0.2)}
    \pgfmathsetmacro{\uax}{\dx/\legad}
    \pgfmathsetmacro{\uay}{\h/\legad}
    \draw[thick] (\rmsz,0) -- (\rmsz+\rmsz*\uax,\rmsz*\uay) -- (\rmsz*\uax,\rmsz*\uay);
  \fi
  % ∠B 直角记号（沿 BA 与 BC 方向）
  \ifnum\rightmarkb>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \ab*0.2, \legbc*0.2)}
    \pgfmathsetmacro{\ubx}{(\dx+\topbase-\ab)/\legbc}
    \pgfmathsetmacro{\uby}{\h/\legbc}
    \draw[thick] (\ab-\rmsz,0) -- (\ab-\rmsz+\rmsz*\ubx,\rmsz*\uby) -- (\ab+\rmsz*\ubx,\rmsz*\uby);
  \fi
  % ∠C 直角记号（沿 CB 与 CD 方向）
  \ifnum\rightmarkc>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \topbase*0.2, \legbc*0.2)}
    \pgfmathsetmacro{\ucx}{(\dx+\topbase-\ab)/\legbc}
    \pgfmathsetmacro{\ucy}{\h/\legbc}
    \draw[thick] (\dx+\topbase-\rmsz*\ucx,\h-\rmsz*\ucy) -- (\dx+\topbase-\rmsz*\ucx-\rmsz,\h-\rmsz*\ucy) -- (\dx+\topbase-\rmsz,\h);
  \fi
  % ∠D 直角记号（沿 DC 与 DA 方向）
  \ifnum\rightmarkd>0
    \pgfmathsetmacro{\rmsz}{min(0.3/\figscale, \topbase*0.2, \legad*0.2)}
    \pgfmathsetmacro{\udx}{-\dx/\legad}
    \pgfmathsetmacro{\udy}{-\h/\legad}
    \draw[thick] (\dx+\rmsz,\h) -- (\dx+\rmsz+\rmsz*\udx,\h+\rmsz*\udy) -- (\dx+\rmsz*\udx,\h+\rmsz*\udy);
  \fi
  % 中位线（虚线，连两腰中点 M、N）
  \ifnum\showmid>0
    \coordinate (M) at (\dx/2,\h/2);
    \coordinate (N) at ({(\ab+\dx+\topbase)/2},\h/2);
    \draw[dashed] (M) -- (N);
    \fill (M) circle [radius=1.6pt];
    \fill (N) circle [radius=1.6pt];
    \node[left=3pt] at (M) {$M$};
    \node[right=3pt] at (N) {$N$};
  \fi
  % D 到下底的高线（虚线，垂足带直角记号）
  \ifnum\showheight>0
    \draw[dashed] (D) -- (\dx,0);
    \fill (\dx,0) circle [radius=1.6pt];
    \node[below=3pt] at (\dx,0) {$\footlabel$};
    \pgfmathsetmacro{\rmh}{min(0.3/\figscale, \h*0.2, \dx*0.5)}
    \draw[thick] (\dx-\rmh,0) -- (\dx-\rmh,\rmh) -- (\dx,\rmh);
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
\end{tikzpicture}
